export default function CardComponent({ selectedCategory, searchResults }) {
    const navigate = useNavigate();
    const [cards, setCards] = useState([]);
    const [filteredCards, setFilteredCards] = useState([]);
    const [likedCards, setLikedCards] = useState({});
    const [showAll, setShowAll] = useState(false);
    const buttonRef = useRef(null);

    useEffect(() => {
        const fetchCards = async () => {
            try {
                const response = await axios.get('http://localhost:5000/api/cards');
                setCards(response.data);
                setFilteredCards(response.data);
            } catch (error) {
                console.error('Error fetching cards:', error);
            }
        };
        fetchCards();
    }, []);

    useEffect(() => {
        if (searchResults) {
            setFilteredCards(searchResults);
        } else if (selectedCategory === "All") {
            setFilteredCards(cards);
        } else {
            setFilteredCards(cards.filter(card => card.location === selectedCategory));
        }
    }, [selectedCategory, searchResults, cards]);

    useEffect(() => {
        const savedLikes = JSON.parse(localStorage.getItem("likedDestinations")) || {};
        setLikedCards(savedLikes);
    }, []);

    const toggleLike = (index) => {
        setLikedCards((prev) => {
            const updatedLikes = { ...prev };
            const cardId = cards[index]._id;

            if (updatedLikes[cardId]) {
                delete updatedLikes[cardId];
            } else {
                updatedLikes[cardId] = cards[index];
            }

            localStorage.setItem("likedDestinations", JSON.stringify(updatedLikes));
            return updatedLikes;
        });
    };

    const handleToggleShowAll = () => {
        setShowAll(!showAll);
        if (showAll && buttonRef.current) {
            buttonRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    };

    return (
        <div>
            <div className='w-full h-auto z-10 overflow-hidden px-7 gap-6 py-9 flex flex-wrap items-start justify-center'>
                <AnimatePresence>
                    {(showAll ? filteredCards : filteredCards.slice(0, 9)).map((card, index) => (
                        <motion.div
                            key={card._id}
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: -20 }}
                            transition={{ duration: 0.5, ease: 'easeInOut' }}
                            className='bg-black w-[330px] h-[450px] rounded-[37px] bg-cover group bg-center opacity-[90%] flex justify-center items-end px-2 pb-2 pt-[305px] hover:py-2 transition-all duration-500'
                            style={{ backgroundImage: `url(${card.imageURL})` }}
                        >
                            <div className='w-full h-full bg-black opacity-[80%] flex flex-col items-center px-4 py-2 rounded-[37px] group-hover:py-16 transition-all duration-500 overflow-hidden'>
                                <div className='flex flex-row h-fit w-full items-center px-2 pt-3'> 
                                    <p className='text-white text-2xl font-Salsa'>{card.title}</p>
                                    <img 
                                        src={likedCards[card._id] 
                                            ? assets.heartfill 
                                            : assets.heart
                                        } 
                                        alt='heart' 
                                        className='w-6 h-6 ml-auto mx-2 cursor-pointer transition-all duration-300' 
                                        onClick={() => toggleLike(index)}
                                    />
                                </div>
                                <div className='flex flex-row h-fit w-full items-center px-1 pt-2'>
                                    <img src={assets.location} className='w-[18px] h-[18px]'/>
                                    <p className='text-white text-sm font-Andika mx-1'>{card.location}</p>
                                </div>
                                <p className='text-white text-sm pt-6 font-Andika mx-6 text-balance mb-10 opacity-0 transition-opacity duration-300 group-hover:opacity-100'>
                                    {card.description}
                                </p>
                                <button 
                                    className='bg-white text-black font-Andika font-semibold opacity-0 transition-opacity duration-300 group-hover:opacity-100 content-center text-m w-1/2 rounded-full px-3 py-2 pt-1'
                                    onClick={() => navigate(`/destination/${card._id}`)}
                                >
                                    Explore more
                                </button>

                            </div>
                        </motion.div>
                    ))}
                </AnimatePresence>
            </div>
            <div className='w-full flex justify-center pb-1 pt-3'>
                <motion.button 
                    ref={buttonRef}
                    whileTap={{ scale: 0.9 }}
                    whileHover={{ scale: 1.05 }}
                    className='bg-white text-black font-Andika font-semibold content-center text-m w-fit rounded-full px-6 py-2 pt-1 transition-all duration-300' 
                    onClick={handleToggleShowAll}
                >
                    {showAll ? 'Show Less' : 'Explore More'}
                </motion.button>
            </div>
        </div>
    );
}

export default function ExtendableCard() {
    const [cards, setCards] = useState([]);
    const [selected, setSelected] = useState(0);
    const navigate = useNavigate();

    useEffect(() => {
        const fetchCards = async () => {
            try {
                const response = await axios.get('http://localhost:5000/api/itinerary-cards');
                setCards(response.data);
            } catch (error) {
                console.error('Error fetching itinerary cards:', error);
            }
        };
        fetchCards();
    }, []);

    return (
        <div className="flex flex-col flex-wrap gap-4 p-9 mx-24 w-full justify-center items-center overflow-x-hidden h-[420px]">
            {cards.map((card, index) => (
                <motion.div
                    key={index}
                    className="relative rounded-[50px] overflow-hidden cursor-pointer"
                    animate={{ width: selected === index ? "375px" : "117px", height: '376px' }}
                    transition={{ type: 'tween', stiffness: 0, damping: 20 }}
                    onClick={() => setSelected(index)}
                >
                    <img src={card.src} alt={card.title} className="w-full h-full object-cover absolute inset-0" />
                    <div className={`absolute inset-0 bg-black bg-opacity-40 flex flex-col justify-end items-center p-4 text-white ${selected === index ? "text-lg flex flex-col justify-center items-center px-16 text-left" : ""}`}>
                        <motion.p
                            transition={{ type: 'inertia', duration: 0.5 }}
                            className={`text-xl font-Salsa text-white w-full text-nowrap ${selected === index ? "flex flex-col justify-center items-center rotate-[0deg] transition-transform duration-200" : "rotate-[-90deg] pl-[340px] h-fit"}`}
                        >
                            {card.title}
                        </motion.p>
                        {selected === index && (
                            <motion.p
                                initial={{ display: 'hidden', opacity: 0 }}
                                animate={{ opacity: 1 }}
                                transition={{ ease: 'easeInOut', duration: 0.5 }}
                                className="text-base mt-2 font-Andika text-white w-full h-fit ease-in-out duration-200"
                            >
                                {card.text}
                            </motion.p>
                        )}
                        {selected === index && (
                            <button className="bg-white text-black font-Andika font-medium my-4 content-center w-1/2 rounded-full px-3 py-2 pt-1"
                            onClick={() =>{ 
                                window.scrollTo(0, 0);
                                navigate(`/itinerary/${card._id}`)}}
                            >
                                Explore
                            </button>
                        )}
                    </div>
                </motion.div>
            ))}
        </div>
    );
}

export default function HiddenspotCard({ selectedCategory, searchQuery }) {
    const navigate = useNavigate();
    const [hiddenspot, setHiddenSpot] = useState([]);
    const [filteredCards, setFilteredCards] = useState([]);
    const [likedCards, setLikedCards] = useState({});
    const [showAll, setShowAll] = useState(false);
    const buttonRef = useRef(null);

    useEffect(() => {
        const fetchCards = async () => {
            try {
                const response = await axios.get('http://localhost:5000/api/hidden-spots');
                setHiddenSpot(response.data);
                setFilteredCards(response.data);
            } catch (error) {
                console.error('Error fetching cards:', error);
            }
        };
        fetchCards();
    }, []);

    useEffect(() => {
        const savedLikes = JSON.parse(localStorage.getItem("likedHiddenSpots")) || {};
        setLikedCards(savedLikes);
    }, []);

    useEffect(() => {
        let filtered = hiddenspot;

        // Filter by selected category
        if (selectedCategory !== "All") {
            filtered = filtered.filter(card => card.location === selectedCategory);
        }

        // Filter by search query
        if (searchQuery.trim() !== "") {
            const query = searchQuery.toLowerCase();
            filtered = filtered.filter(card => 
                card.title.toLowerCase().includes(query) || 
                card.location.toLowerCase().includes(query)
            );
        }

        setFilteredCards(filtered);
    }, [selectedCategory, searchQuery, hiddenspot]);

    const toggleLike = (card) => {
        setLikedCards((prev) => {
            const updatedLikes = { ...prev };
            if (updatedLikes[card._id]) {
                delete updatedLikes[card._id];
            } else {
                updatedLikes[card._id] = card;
            }
            localStorage.setItem("likedHiddenSpots", JSON.stringify(updatedLikes));
            return updatedLikes;
        });
    };

    const handleToggleShowAll = () => {
        setShowAll(!showAll);
        if (showAll && buttonRef.current) {
            buttonRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    };

    return (
        <div>
            <div className='w-full h-auto z-10 overflow-hidden px-7 gap-6 py-9 flex flex-wrap items-start justify-center'>
                <AnimatePresence>
                    {(showAll ? filteredCards : filteredCards.slice(0, 9)).map((card) => (
                        <motion.div
                            key={card._id}
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: -20 }}
                            transition={{ duration: 0.5, ease: 'easeInOut' }}
                            className='bg-black w-[330px] h-[450px] rounded-[37px] bg-cover group bg-center opacity-[90%] flex justify-center items-end px-2 pb-2 pt-[305px] hover:py-2 transition-all duration-500'
                            style={{ backgroundImage: `url(${card.src})` }}
                        >
                            <div className='w-full h-full bg-black opacity-[80%] flex flex-col items-center px-4 py-2 rounded-[37px] group-hover:py-16 transition-all duration-500 overflow-hidden'>
                                <div className='flex flex-row h-fit w-full items-center px-2 pt-3'> 
                                    <p className='text-white text-2xl font-Salsa'>{card.title}</p>
                                    <img 
                                        src={likedCards[card._id] ? assets.heartfill : assets.heart} 
                                        alt='heart' 
                                        className='w-6 h-6 ml-auto mx-2 cursor-pointer transition-all duration-300' 
                                        onClick={(e) => { e.stopPropagation(); toggleLike(card); }} // ✅ Prevents click propagation
                                    />
                                </div>
                                <div className='flex flex-row h-fit w-full items-center px-1 pt-2'>
                                    <img src={assets.location} className='w-[18px] h-[18px]'/>
                                    <p className='text-white text-sm font-Andika mx-1'>{card.location}</p>
                                </div>
                                <p className='text-white text-sm pt-6 font-Andika mx-6 text-balance mb-10 opacity-0 transition-opacity duration-300 group-hover:opacity-100'>
                                    {card.text}
                                </p>
                                <button className='bg-white text-black font-Andika font-semibold opacity-0 transition-opacity duration-300 group-hover:opacity-100 content-center text-m w-1/2 rounded-full px-3 py-2 pt-1'
                            onClick={() => navigate(`/hidden-spot/${card._id}`)} // ✅ Navigate to DestinationPage
                            >
                                    Explore more
                                </button>
                            </div>
                        </motion.div>
                    ))}
                </AnimatePresence>
            </div>
            <div className='w-full flex justify-center pb-1 pt-3'>
                <motion.button 
                    ref={buttonRef}
                    whileTap={{ scale: 0.9 }}
                    whileHover={{ scale: 1.05 }}
                    className='bg-white text-black font-Andika font-semibold content-center text-m w-fit rounded-full px-6 py-2 pt-1 transition-all duration-300' 
                    onClick={handleToggleShowAll}
                >
                    {showAll ? 'Show Less' : 'Explore More'}
                </motion.button>
            </div>
        </div>
    );
}

export default function DestinationPage() {
    const navigate = useNavigate();
    const { id } = useParams();  // ✅ Get the card ID from the URL
    const [destination, setDestination] = useState(null);
    const [loading, setLoading] = useState(true);
    const [scrollPosition, setScrollPosition] = useState(0);
    const [weather, setWeather] = useState(null);

useEffect(() => {
    if (!destination?.location) return;  // Ensure destination and location are available

    const fetchWeather = async () => {
        try {
            const response = await fetch(`https://api.weatherapi.com/v1/current.json?key=${API_KEY}&q=${destination.location}`);
            const data = await response.json();

            setWeather({
                temp: Math.round(data.current.temp_c),  // ✅ Get correct temperature
                condition: data.current.condition.text, // ✅ Get weather condition text
                icon: data.current.condition.icon, // ✅ Get weather icon
            });
        } catch (error) {
            console.error("Error fetching weather data:", error);
        }
    };

    fetchWeather();
}, [destination]);  // ✅ Fetch weather only when destination updates


  
    useEffect(() => {
        const fetchDestination = async () => {
            if (!id) return; // Ensure ID is present

            try {
                const response = await axios.get(`http://localhost:5000/api/cards/${id}`);
                setDestination(response.data);
            } catch (error) {
                console.error("Error fetching destination:", error);
                setDestination(null);
            } finally {
                setLoading(false);
            }
        };

        fetchDestination();
    }, [id]);

    // ✅ Handle Scroll Event Efficiently
    const handleScroll = useCallback(() => {
        setScrollPosition(window.scrollY);
    }, []);

    useEffect(() => {
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, [handleScroll]); 

    // ✅ Loading and Error Handling
    if (loading) return <p className="text-white text-center">Loading...</p>;
    if (!destination) return <p className="text-white text-center">Destination not found</p>;

    // ✅ Optimized Parallax Effect
    const calculateImageStyle = () => {
        const startTransform = window.innerHeight * 0.5;
        const endTransform = window.innerHeight * 1.5;
        const progress = Math.max(0, Math.min((scrollPosition - startTransform) / (endTransform - startTransform), 1));

        const finalTop = 64;
        const finalRight = window.innerWidth - (window.innerWidth * 0.000051) + 320;
        const scale = 1 - (progress * 0.5);
        const translateY = progress * finalTop;
        const translateX = progress * finalRight;
        const isLocked = scrollPosition > endTransform;

        return {
            transform: isLocked 
                ? `translate(${finalRight}px, ${finalTop}px) scale(0.5)`
                : `translate(${translateX}px, ${translateY}px) scale(${scale})`,
            opacity: 1,
            width: progress === 0 ? '100vw' : '482px',
            height: progress === 0 ? '100vh' : '594px',
            backgroundImage: `url(${destination.imageURL})`,  // ✅ Dynamic image
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            position: 'fixed',
            top: 0,
            left: 0,
            transition: isLocked ? 'none' : 'all 300ms ease-out',
            zIndex: 4,
        };
    };

    return (
        <div className="relative">
            {/* First Section with Parallax Image */}
            <div className="h-screen relative bg-black overflow-hidden">
                <div style={calculateImageStyle()} />
                <NavBar />
                <div className="relative h-full flex items-end justify-start">
                    <div className="text-white text-center p-8 bg-opacity-30 rounded-lg" style={{ zIndex: 20 }}>
                        <p className='font-Pottaone min-[1440px]:text-7xl text-5xl pb-3 text-white'>
                            {destination.title}
                        </p>
                        <div className='flex flex-row items-center'>
                            <img src={assets.location} className='w-[18px] h-[18px]' />
                            <p className='font-Ubuntu min-[1440px]:text-5xl pl-1 text-2xl text-white'>
                                {destination.location}
                            </p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Second Section */}
            <div className="h-screen bg-black backdrop-blur-sm p-12 relative" style={{ zIndex: 2 }}>
                <div className="max-w-[50%] py-10 ml-8 h-fit text-white p-8">
                    <div className="text-white p-8 bg-opacity-30 rounded-lg" style={{ zIndex: 20 }}>
                        <div className='flex flex-col justify-start w-full'>
                            <p className='font-Pottaone min-[1440px]:text-7xl text-5xl pb-3 text-white'>
                                {destination.title}
                            </p>
                            <div className='flex flex-row items-center'>
                                <img src={assets.location} className='w-[18px] h-[18px]' />
                                <p className='font-Ubuntu min-[1440px]:text-5xl pl-1 text-2xl text-white'>
                                    {destination.location}
                                </p>
                            </div>
                        </div>
                    </div>
                    <p className="font-Ubuntu text-2xl text-white">
                        {destination.landingDescription}
                    </p>
                </div>
            </div>

            {/* Weather and Other Sections */}
            <div className='bg-black h-screen w-full justify-center flex flex-col items-start gap-14 p-2' style={{ zIndex: 2 }}>
                <div className='w-full h-fit items-center justify-center flex' style={{ flex: 0.5 }}>
                    <div className='linear-weather w-fit h-fit bg-opacity-5 rounded-[35px]'>
                        <div className='flex flex-col bg-transparent glass-effect rounded-[35px] p-2 justify-center items-center'>
                            <div className='flex flex-row w-full h-fit'>
                                <div className='flex flex-col justify-center items-center w-full px-10' style={{ flex: 2 }}>
                                    <img src={assets.weather} className='w-[130px] h-[88px]' />
                                    <p className='text-base font-Andika text-white py-1'>
                                        {weather?.condition || 'Loading...'}
                                    </p>
                                </div>
                                <div className='flex items-center justify-center' style={{ flex: 0.2 }}>
                                    <img src={assets.line} className='h-[110px]' />
                                </div>
                                <div className='w-full flex flex-col items-center justify-center px-10' style={{ flex: 2 }}>
                                    <div className='w-full'>
                                        <p className='text-[15px] text-white font-UbuntuBold uppercase text-nowrap py-1'>
                                        {destination.title}
                                        </p>
                                        <p className='text-[15px] text-white font-UbuntuBold uppercase text-nowrap py-1'>
                                        {destination.location}
                                        </p>
                                        <p className='text-[33px] font-bold text-white font-salsa'>
                                            {weather?.temp ? `${weather.temp}°C` : 'Loading...'}
                                        </p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
                <div className='w-full h-fit items-center justify-center flex' style={{ flex:0.3 }}>
                <GoogleMapComponent lat={destination.lat} lng={destination.lng} />
                </div>
            </div>

            {/* Hidden Gems Section */}
            <div className='w-full bg-black'>
                <div className='flex flex-col items-center justify-center'>
                    <p className='text-white text-4xl font-McLaren text-center pt-6'>
                        Hidden Gems
                    </p>
                    <p className='font-Andika text-white text-center min-[1440px]:text-base text-m py-2 w-[45%]'>
                        "Unlock the unknown"
                    </p>
                </div>
                <HiddenCards />
                <div className='w-full flex justify-center pb-10'>
                    <button className='bg-white text-black font-Andika font-semibold text-m w-fit rounded-full px-6 py-2 pt-1'>
                        <a onClick={() => {
                            window.scrollTo(0, 0); 
                            navigate("/hidden-spot");
                        }}>
                            Explore
                        </a>
                    </button>
                </div>
            </div>

            <FooterElement />
        </div>
    );
}

